<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.Scanner;

public class Solution {
    private static int countWords(String text) {
        int count = 0;
        for (String word : text.split("_")) {
            if (!word.isEmpty()) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        in.nextLine();
        String line = in.nextLine();
        final int originalLength = line.length();

        StringBuilder out = new StringBuilder(line);
        int insideWords = 0;
        int open = out.indexOf("(");

        while (open != -1) {
            int close = out.indexOf(")", open + 1);
            if (close == -1) {
                throw new StringIndexOutOfBoundsException(originalLength);
            }

            insideWords += countWords(out.substring(open + 1, close));
            out.replace(open, close + 1, "_");
            open = out.indexOf("(", open + 1);
        }

        int max = 0;
        for (String word : out.toString().split("_")) {
            if (!word.isEmpty() && word.length() > max) {
                max = word.length();
            }
        }

        System.out.println(max + " " + insideWords);
        in.close();
    }
}
